INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `childcategory_id`, `brand_id`, `product_code`, `purchase_price`, `old_price`, `new_price`, `stock`, `pro_unit`, `pro_video`, `description`, `meta_description`, `topsale`, `flashsale`, `feature_product`, `campaign_id`, `status`, `sold`, `note`, `created_at`, `updated_at`) VALUES
(180, 'গোলমরিচ - ৫০ গ্রাম', 'গোলমরিচ---৫০-গ্রাম-200', 14, 0, NULL, 18, 'P0180', 140, NULL, 115, 1000, NULL, NULL, '<div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\">রান্নায় আসুক রাজকীয় স্বাদ আর ঝাঁঝ—ক্লাসি (Classy) প্রিমিয়াম কালো গোল মরিচের সাথে! <span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"🖤\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t0/1/16/1f5a4.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"🍲\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t66/1/16/1f372.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span></div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\">​মসলার রাজা বলা হয় গোল মরিচকে। শুধু স্বাদ বাড়ানোই নয়, রান্নায় আভিজাত্য আর স্বাস্থ্যগুণ যোগ করতে এর জুড়ি নেই। Classy আপনাদের জন্য নিয়ে এসেছে একদম বাছাইকৃত, ধুলোবালি মুক্ত এবং শতভাগ খাঁটি কালো গোল মরিচ (Black Pepper)।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\">​কেন আমাদের গোল মরিচ আপনার রান্নাঘরে থাকা চাই?</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✅\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t33/1/16/2705.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> তীব্র ঘ্রাণ ও স্বাদ: একদম সতেজ দানা থেকে তৈরি, যা আপনার খাবারে আনবে প্রাকৃতিক ঝাঁঝ।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✅\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t33/1/16/2705.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> শতভাগ বিশুদ্ধ: কোনো ভেজাল বা কৃত্রিম রঙ নেই, সরাসরি কৃষকের বাগান থেকে সংগৃহীত।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✅\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t33/1/16/2705.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> স্বাস্থ্যগুণে ভরপুর: হজম শক্তি বাড়াতে, ওজন কমাতে এবং ঠান্ডা-কাশি উপশমে গোল মরিচ জাদুর মতো কাজ করে।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✅\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t33/1/16/2705.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> নিখুঁত প্যাকেজিং: আমাদের প্রিমিয়াম প্যাকেজিং মসলার গুণগত মান ও ঘ্রাণ দীর্ঘক্ষণ অটুট রাখে।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\">​কালো গোল মরিচের বহুমুখী ব্যবহার:</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✨\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tf4/1/16/2728.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> মাংসের মেরিনেশনে ও রান্নায়।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✨\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tf4/1/16/2728.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> স্যুপ, সালাদ বা পাস্তায় স্বাদের মাত্রা বাড়াতে।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✨\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tf4/1/16/2728.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> ওজন কমাতে সকালে হালকা গরম জলের সাথে।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\"><span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"✨\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tf4/1/16/2728.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span> ভেষজ চা বা মশলা চা তৈরিতে।</div><div dir=\"auto\" style=\"font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif; white-space-collapse: preserve;\">​প্রিমিয়াম কোয়ালিটির এই কালো গোল মরিচ এখন পাওয়া যাচ্ছে আকর্ষণীয় ৫০ গ্রামের প্যাকে।</div>', NULL, 0, NULL, 0, NULL, 1, NULL, NULL, '2026-03-28 14:22:59', '2026-03-29 09:56:57'),
(181, 'গুঁড়া মরিচ - ২০০ গ্রাম', 'গুঁড়া-মরিচ---২০০-গ্রাম-204', 16, 0, NULL, 18, 'P0181', 100, NULL, 140, 1000, NULL, NULL, '<div class=\"xdj266r x14z9mp xat24cr x1lziwak x1vvkbs x126k92a\" style=\"overflow-wrap: break-word; white-space-collapse: preserve; margin-inline: 0px; margin-bottom: 0px; margin-top: 0px; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif;\"><div dir=\"auto\" style=\"font-family: inherit;\">রান্নায় আসুক ঝাল আর রঙের পারফেক্ট ব্যালেন্স! ব্যবহার করুন \'Classy\' মরিচের গুঁড়া! <span class=\"html-span xexx8yu xyri2b x18d9i69 x1c1uobl x1hl2dhg x16tdsg8 x1vvkbs x3nfvp2 x1j61x8r x1fcty0u xdj266r xat24cr xm2jcoa x1mpyi22 xxymvpz xlup9mm x1kky2od\" style=\"text-align: inherit; overflow-wrap: break-word; display: inline-flex; vertical-align: middle; width: 16px; height: 16px; margin-inline: 1px; padding-inline: 0px; padding-bottom: 0px; margin-bottom: 0px; margin-top: 0px; padding-top: 0px; font-family: inherit;\"><img height=\"16\" width=\"16\" class=\"xz74otr x15mokao x1ga7v0g x16uus16 xbiv7yw\" alt=\"🌶️\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/tee/1/16/1f336.png\" style=\"border: 0px; border-start-start-radius: 0px; border-end-end-radius: 0px; border-start-end-radius: 0px; border-end-start-radius: 0px; object-fit: fill;\"></span></div></div><div class=\"x14z9mp xat24cr x1lziwak x1vvkbs xtlvy1s x126k92a\" style=\"overflow-wrap: break-word; white-space-collapse: preserve; margin-top: 0.5em; margin-inline: 0px; margin-bottom: 0px; font-family: &quot;Segoe UI Historic&quot;, &quot;Segoe UI&quot;, Helvetica, Arial, sans-serif;\"><div dir=\"auto\" style=\"font-family: inherit;\">আপনার প্রতিদিনের রান্নাকে আরও ঝালমশলাদার এবং আকর্ষণীয় করতে আমরা নিয়ে এসেছি প্রিমিয়াম কোয়ালিটির মরিচের গুঁড়া। বাছাইকৃত সেরা মানের শুকনো মরিচ থেকে স্বাস্থ্যসম্মত উপায়ে প্রস্তুতকৃত এই গুঁড়া আপনার খাবারে যোগ করবে প্রাকৃতিক গাঢ় লাল রঙ এবং আসল ঝাল।</div></div><div class=\"x14z9mp xat24cr x